"use client";
import { useRef, useState } from "react";
import ReactMarkdown from "react-markdown";
import remarkGfm from "remark-gfm";
import rehypeRaw from "rehype-raw";
import rehypeHighlight from "rehype-highlight";
import { MD_COMPONENTS, MD_URL_TRANSFORM } from "@/lib/md-components";

const REMARK_PLUGINS = [remarkGfm];
const REHYPE_FULL = [rehypeRaw, rehypeHighlight];

type Phase = "idle" | "rendering" | "copied" | "downloaded" | "error";

// Replaces the old "存到记忆" action: render this Q&A into a shareable card
// PNG and drop it on the clipboard so the user can paste it straight into
// chat / notes. Falls back to a file download where the browser blocks
// programmatic image clipboard writes (older Safari / Firefox).
export function CardImageButton({
  title,
  content,
}: {
  title: string;
  content: string;
}) {
  const cardRef = useRef<HTMLDivElement>(null);
  const [phase, setPhase] = useState<Phase>("idle");

  const run = async () => {
    if (phase === "rendering" || !cardRef.current) return;
    setPhase("rendering");
    const card = cardRef.current;
    const wrapper = card.parentElement;
    // Save the original wrapper style so we can restore it after rendering.
    const prevStyle = wrapper?.getAttribute("style") ?? "";
    try {
      // html-to-image rasterizes the element via an SVG <foreignObject>.
      // Elements parked off-screen with `left: -99999px` can come out blank
      // in some browsers (the foreignObject viewport clips to the element's
      // bounding rect, which sits outside the rendered area). Move the card
      // to a real on-screen position for the duration of the render, then
      // restore. `z-index: -1` keeps it behind the page content so the user
      // never sees it flash.
      if (wrapper) {
        wrapper.setAttribute(
          "style",
          "position:fixed;left:0;top:0;z-index:-1;pointer-events:none;",
        );
      }
      // Lazy-load the rasterizer so it stays out of the main bundle.
      const { toBlob } = await import("html-to-image");
      const isDark = document.documentElement.classList.contains("dark");
      const blob = await toBlob(card, {
        pixelRatio: 2,
        backgroundColor: isDark ? "#1c1917" : "#ffffff",
        cacheBust: true,
      });
      if (!blob) throw new Error("render produced no image");

      // Prefer the clipboard; fall back to a download if it's unavailable
      // or rejected (permissions / unsupported ClipboardItem image type).
      const canClipImage =
        typeof ClipboardItem !== "undefined" &&
        !!navigator.clipboard?.write;
      if (canClipImage) {
        try {
          await navigator.clipboard.write([
            new ClipboardItem({ "image/png": blob }),
          ]);
          setPhase("copied");
        } catch {
          downloadBlob(blob, title);
          setPhase("downloaded");
        }
      } else {
        downloadBlob(blob, title);
        setPhase("downloaded");
      }
      window.setTimeout(() => setPhase("idle"), 2000);
    } catch (err) {
      console.error("[trellis] card image failed:", err);
      setPhase("error");
      window.setTimeout(() => setPhase("idle"), 2500);
    } finally {
      if (wrapper) wrapper.setAttribute("style", prevStyle);
    }
  };

  const label =
    phase === "rendering"
      ? "生成中…"
      : phase === "copied"
        ? "✓ 已复制图片"
        : phase === "downloaded"
          ? "✓ 已下载"
          : phase === "error"
            ? "✗ 失败"
            : "🖼 卡片图";

  return (
    <>
      <button
        type="button"
        onClick={(e) => {
          e.stopPropagation();
          void run();
        }}
        disabled={phase === "rendering"}
        title="把这条问答渲染成一张卡片图片并复制到剪贴板"
        className="nodrag px-2.5 py-1 rounded border border-line text-ui text-ink-muted hover:bg-surface-muted hover:text-ink-strong transition-colors disabled:opacity-50"
      >
        {label}
      </button>

      {/* Off-screen card laid out (not display:none, which can't be
          rasterized) for html-to-image to capture. Mirrors the app's markdown
          styling so the image matches what the user reads. The wrapper is
          temporarily repositioned on-screen during render — see run(). */}
      <div
        aria-hidden
        style={{ position: "fixed", left: -99999, top: 0, pointerEvents: "none" }}
      >
        <div
          ref={cardRef}
          className="w-[680px] bg-surface px-8 py-7"
        >
          <div className="flex items-start gap-3 mb-5">
            <span className="mt-1 w-1 self-stretch rounded-full bg-accent shrink-0" />
            <h3 className="text-title leading-snug font-semibold text-ink-strong">
              {title}
            </h3>
          </div>
          <div className="md-body text-ink">
            <ReactMarkdown
              remarkPlugins={REMARK_PLUGINS}
              rehypePlugins={REHYPE_FULL}
              components={MD_COMPONENTS}
              urlTransform={MD_URL_TRANSFORM}
            >
              {content}
            </ReactMarkdown>
          </div>
          <div className="mt-6 pt-3 border-t border-line/70 text-label text-ink-faint">
            Trellis · 思维树
          </div>
        </div>
      </div>
    </>
  );
}

function downloadBlob(blob: Blob, title: string) {
  const url = URL.createObjectURL(blob);
  const a = document.createElement("a");
  a.href = url;
  const slug =
    title.slice(0, 40).replace(/[^\p{L}\p{N}]+/gu, "-").replace(/^-|-$/g, "") ||
    "trellis-card";
  a.download = `${slug}.png`;
  document.body.appendChild(a);
  a.click();
  a.remove();
  window.setTimeout(() => URL.revokeObjectURL(url), 1000);
}

"use client";
import { useState } from "react";
import { useSessionStore } from "@/stores/sessionStore";
import { Button } from "./ui/Button";
import { copyText } from "@/lib/clipboard";

// 「在 CLI 继续」轻量入口：project 模式会话本就是真 claude CLI 会话，点一下把
// `cd <ws> && claude --resume <id>` 复制到剪贴板，去终端粘贴即可续这条 lineage。
// 仅 project 模式渲染；不可续（源 jsonl 已不在盘等）→ 提示「盘上找不到」。
// 树内分叉的「在 CLI 续任意分支」需 P2 前缀 jsonl，不在本入口范围（见 spec）。
type State = "idle" | "loading" | "copied" | "none";

export function CliResumeButton({ nodeId }: { nodeId: string }) {
  const mode = useSessionStore((s) => s.session?.mode);
  const [state, setState] = useState<State>("idle");
  if (mode !== "project") return null;

  const onClick = async (e: React.MouseEvent) => {
    e.stopPropagation();
    if (state === "loading") return;
    setState("loading");
    try {
      const res = await fetch(`/api/nodes/${nodeId}/cli-resume`);
      const data = (await res.json()) as { resumable?: boolean; command?: string };
      if (data.resumable && data.command) {
        try {
          await copyText(data.command);
        } catch {
          /* clipboard unavailable — still show success, user can re-copy */
        }
        setState("copied");
      } else {
        setState("none");
      }
    } catch {
      setState("none");
    }
    window.setTimeout(() => setState("idle"), 2200);
  };

  const label =
    state === "copied"
      ? "✓ 命令已复制"
      : state === "none"
        ? "盘上找不到"
        : state === "loading"
          ? "…"
          : "⌨ 在 CLI 继续";

  return (
    <Button
      type="button"
      variant="secondary"
      size="sm"
      onClick={onClick}
      title="复制 cd + CLI 续聊命令（claude --resume / codex resume），到终端粘贴即可续这条对话"
      className="nodrag"
    >
      {label}
    </Button>
  );
}

"use client";
import { useRef, useState, isValidElement, type ReactNode } from "react";
import { copyText } from "@/lib/clipboard";

// Custom react-markdown `pre` renderer: wraps the highlighted <pre> in a
// frame with a top bar showing the language label + a copy button (A3/B2).
// Copy reads pre.textContent — robust against rehype-highlight splitting the
// source into nested <span> tokens, since textContent flattens back to source.
function langOf(children: ReactNode): string {
  if (isValidElement(children)) {
    const cn = (children.props as { className?: string }).className ?? "";
    const m = /language-([\w-]+)/.exec(cn);
    if (m) return m[1];
  }
  return "";
}

export function CodeBlock({ children }: { children?: ReactNode; node?: unknown }) {
  const preRef = useRef<HTMLPreElement>(null);
  const [copied, setCopied] = useState(false);
  const [failed, setFailed] = useState(false);
  const lang = langOf(children);

  const copy = async (e: React.MouseEvent) => {
    e.stopPropagation();
    const text = preRef.current?.textContent ?? "";
    if (!text) return;
    try {
      await copyText(text);
      setFailed(false);
      setCopied(true);
      window.setTimeout(() => setCopied(false), 1500);
    } catch (err) {
      console.error("[trellis] code copy failed:", err);
      setFailed(true);
      window.setTimeout(() => setFailed(false), 2000);
    }
  };

  return (
    <div className="md-codeblock">
      <div className="md-codeblock-bar" contentEditable={false}>
        <span className="md-codeblock-lang">{lang || "code"}</span>
        <button
          type="button"
          onClick={copy}
          className="md-codeblock-copy nodrag"
          aria-label="复制代码"
        >
          {failed ? "✗ 失败" : copied ? "✓ 已复制" : "复制"}
        </button>
      </div>
      <pre ref={preRef}>{children}</pre>
    </div>
  );
}

"use client";
import { useState } from "react";
import { copyText } from "@/lib/clipboard";

// Shared "copy to clipboard" button with a transient ✓ confirmation.
// Used for "copy whole reply" in ChatNode/NodeFullView footers. Code-block
// copy lives in CodeBlock.tsx (different layout, same clipboard pattern).
export function CopyButton({
  text,
  label = "复制",
  copiedLabel = "✓ 已复制",
  className,
  title = "复制全文（markdown 源）",
}: {
  text: string;
  label?: string;
  copiedLabel?: string;
  className?: string;
  title?: string;
}) {
  const [copied, setCopied] = useState(false);
  const [failed, setFailed] = useState(false);

  const copy = async (e: React.MouseEvent) => {
    e.stopPropagation();
    if (!text) return;
    try {
      await copyText(text);
      setFailed(false);
      setCopied(true);
      window.setTimeout(() => setCopied(false), 1500);
    } catch (err) {
      console.error("[trellis] copy failed:", err);
      setFailed(true);
      window.setTimeout(() => setFailed(false), 2000);
    }
  };

  return (
    <button
      type="button"
      onClick={copy}
      title={title}
      aria-label="复制全文"
      className={
        className ??
        "nodrag px-2 py-0.5 rounded text-ink-muted hover:bg-surface-muted hover:text-ink-strong transition-colors"
      }
    >
      {failed ? "✗ 复制失败" : copied ? copiedLabel : label}
    </button>
  );
}

"use client";

// Shared clipboard helpers. The async Clipboard API (navigator.clipboard)
// is only available in secure contexts (https / localhost) and requires a
// user gesture. When it's unavailable or rejects, fall back to the legacy
// `document.execCommand('copy')` path, which works everywhere but needs a
// focused textarea with the text selected.

export async function copyText(text: string): Promise<void> {
  if (!text) return;

  // 1) Modern async clipboard API.
  if (navigator.clipboard?.writeText) {
    try {
      await navigator.clipboard.writeText(text);
      return;
    } catch {
      // fall through to the execCommand fallback
    }
  }

  // 2) Legacy execCommand fallback. Create a hidden textarea, select its
  //    contents, run copy, then remove it. Must be synchronous-ish (no
  //    await between focus and execCommand) or the browser may treat the
  //    gesture as expired.
  const ta = document.createElement("textarea");
  ta.value = text;
  ta.setAttribute("readonly", "");
  ta.style.position = "fixed";
  ta.style.left = "-9999px";
  ta.style.top = "0";
  ta.style.opacity = "0";
  document.body.appendChild(ta);
  ta.focus();
  ta.select();
  ta.setSelectionRange(0, text.length);
  try {
    const ok = document.execCommand("copy");
    if (!ok) throw new Error("execCommand('copy') returned false");
  } finally {
    document.body.removeChild(ta);
  }
}

