2	import { useEffect, useRef, useState } from "react";
3	import { createPortal } from "react-dom";
4	import ReactMarkdown from "react-markdown";
5	import { Modal } from "./ui/Modal";
6	import { MD_COMPONENTS, MD_URL_TRANSFORM } from "@/lib/md-components";
7	import {
8	  MARKDOWN_REHYPE_PLUGINS,
9	  MARKDOWN_REMARK_PLUGINS,
10	} from "@/lib/markdown-plugins";
11	
12	type Phase = "idle" | "rendering" | "error";
13	
14	// Renders this Q&A into a shareable card PNG, then opens a preview dialog
15	// where the user picks the destination themselves — copy to clipboard or
16	// download as a file (the old auto-copy-with-silent-download-fallback made
17	// the outcome unpredictable across browsers).
18	export function CardImageButton({
19	  title,
20	  content,
21	}: {
22	  title: string;
23	  content: string;
24	}) {
25	  const cardRef = useRef<HTMLDivElement>(null);
26	  const [phase, setPhase] = useState<Phase>("idle");
27	  const [blob, setBlob] = useState<Blob | null>(null);
28	
29	  const run = async () => {
30	    if (phase === "rendering" || !cardRef.current) return;
31	    setPhase("rendering");
32	    try {
33	      // Lazy-load the rasterizer so it stays out of the main bundle.
34	      const { toBlob } = await import("html-to-image");
35	      const isDark = document.documentElement.classList.contains("dark");
36	      const rendered = await toBlob(cardRef.current, {
37	        pixelRatio: 2,
38	        backgroundColor: isDark ? "#1c1917" : "#ffffff",
39	        cacheBust: true,
40	      });
41	      if (!rendered) throw new Error("render produced no image");
42	      setBlob(rendered);
43	      setPhase("idle");
44	    } catch (err) {
45	      console.error("[trellis] card image failed:", err);
46	      setPhase("error");
47	      window.setTimeout(() => setPhase("idle"), 2500);
48	    }
49	  };
50	
51	  const label =
52	    phase === "rendering"
53	      ? "生成中…"
54	      : phase === "error"
55	        ? "✗ 失败"
56	        : "🖼 卡片图";
57	
58	  return (
59	    <>
60	      <button
61	        type="button"
62	        onClick={(e) => {
63	          e.stopPropagation();
64	          void run();
65	        }}
66	        disabled={phase === "rendering"}
67	        title="把这条问答渲染成一张卡片图片"
68	        className="nodrag px-2.5 py-1 rounded border border-line text-ui text-ink-muted hover:bg-surface-muted hover:text-ink-strong transition-colors disabled:opacity-50"
69	      >
70	        {label}
71	      </button>
72	
73	      {blob && (
74	        <CardPreviewDialog
75	          blob={blob}
76	          title={title}
77	          onClose={() => setBlob(null)}
78	        />
79	      )}
80	
81	      {/* Off-screen card laid out (not display:none, which can't be
82	          rasterized) for html-to-image to capture. Mirrors the app's markdown
83	          styling so the image matches what the user reads. */}
84	      <div
85	        aria-hidden
86	        style={{ position: "fixed", left: -99999, top: 0, pointerEvents: "none" }}
87	      >
88	        <div
89	          ref={cardRef}
90	          className="w-[680px] bg-surface px-8 py-7"
91	        >
92	          <div className="flex items-start gap-3 mb-5">
93	            <span className="mt-1 w-1 self-stretch rounded-full bg-accent shrink-0" />
94	            <h3 className="text-title leading-snug font-semibold text-ink-strong">
95	              {title}
96	            </h3>
97	          </div>
98	          <div className="md-body text-ink">
99	            <ReactMarkdown
100	              remarkPlugins={MARKDOWN_REMARK_PLUGINS}
101	              rehypePlugins={MARKDOWN_REHYPE_PLUGINS}
102	              components={MD_COMPONENTS}
103	            urlTransform={MD_URL_TRANSFORM}
104	            >
105	              {content}
106	            </ReactMarkdown>
107	          </div>
108	          <div className="mt-6 pt-3 border-t border-line/70 text-label text-ink-faint">
109	            Trellis · 思维树
110	          </div>
111	        </div>
112	      </div>
113	    </>
114	  );
115	}
116	
117	// Portalled to body: TurnCard lives inside a transformed React Flow node,
118	// where a plain fixed-position Modal would anchor to the node, not the
119	// viewport.
120	function CardPreviewDialog({
121	  blob,
122	  title,
123	  onClose,
124	}: {
125	  blob: Blob;
126	  title: string;
127	  onClose: () => void;
128	}) {
129	  const [url] = useState(() => URL.createObjectURL(blob));
130	  const [copyState, setCopyState] = useState<"idle" | "copied" | "failed">(
131	    "idle",
132	  );
133	  useEffect(() => () => URL.revokeObjectURL(url), [url]);
134	
135	  const copy = async () => {
136	    try {
137	      if (typeof ClipboardItem === "undefined" || !navigator.clipboard?.write) {
138	        throw new Error("clipboard image write unsupported");
139	      }
140	      await navigator.clipboard.write([
141	        new ClipboardItem({ "image/png": blob }),
142	      ]);
143	      setCopyState("copied");
144	      window.setTimeout(() => setCopyState("idle"), 2000);
145	    } catch (err) {
146	      console.error("[trellis] card image copy failed:", err);
147	      setCopyState("failed");
148	    }
149	  };
150	
151	  return createPortal(
152	    <div className="nodrag nowheel" onClick={(e) => e.stopPropagation()}>
153	      <Modal onClose={onClose} size="lg">
154	        <div className="flex items-center justify-between px-5 py-3 border-b border-line">
155	          <span className="text-ui font-medium text-ink-strong">卡片图</span>
156	          <button
157	            type="button"
158	            onClick={onClose}
159	            className="px-2 py-0.5 rounded text-ui text-ink-muted hover:bg-surface-muted hover:text-ink-strong transition-colors"
160	          >
161	            ✕
162	          </button>
163	        </div>
164	        <div className="max-h-[60vh] overflow-auto p-4 bg-surface-muted/40">
165	          {/* eslint-disable-next-line @next/next/no-img-element */}
166	          <img
167	            src={url}
168	            alt={`卡片图预览：${title}`}
169	            className="w-full rounded border border-line"
170	          />
171	        </div>
172	        <div className="flex gap-2 px-5 py-3 border-t border-line">
173	          <button
174	            type="button"
175	            onClick={() => void copy()}
176	            className="flex-1 px-3 py-1.5 rounded border border-line text-ui text-ink hover:bg-surface-muted hover:text-ink-strong transition-colors"
177	          >
178	            {copyState === "copied"
179	              ? "✓ 已复制"
180	              : copyState === "failed"
181	                ? "复制失败，请用下载"
182	                : "复制图片"}
183	          </button>
184	          <button
185	            type="button"
186	            onClick={() => downloadBlob(blob, title)}
187	            className="flex-1 px-3 py-1.5 rounded bg-accent text-white text-ui hover:opacity-90 transition-opacity"
188	          >
189	            下载图片
190	          </button>
191	        </div>
192	      </Modal>
193	    </div>,
194	    document.body,
195	  );
196	}
197	
198	function downloadBlob(blob: Blob, title: string) {
199	  const url = URL.createObjectURL(blob);
200	  const a = document.createElement("a");
201	  a.href = url;
202	  const slug =
203	    title.slice(0, 40).replace(/[^\p{L}\p{N}]+/gu, "-").replace(/^-|-$/g, "") ||
204	    "trellis-card";
205	  a.download = `${slug}.png`;
206	  document.body.appendChild(a);
207	  a.click();
208	  a.remove();
209	  window.setTimeout(() => URL.revokeObjectURL(url), 1000);
210	}
